DELETE FROM `scc_base_todolist_config` WHERE `TODOLIST_CONFIG_ID`=459508800388864;
INSERT INTO `scc_base_todolist_config` (`TODOLIST_CONFIG_ID`, `UNIQUE_CODE`, `CONFIG_MODULE`, `CONFIG_CODE`, `CONFIG_NAME`, `CONFIG_TYPE`, `CONFIG_FROM`, `CONFIG_VERSION`, `CONFIG_STATUS`, `ROLE_CODE`, `DIMENSION`, `CONFIG_MODE`, `SQL_LANGUAGE`, `URL_ADDRESS`, `URL_PARAMS`, `URL_MAPPING`, `FRONT_ROUTE_NAME`, `FRONT_FORM_NAME`, `FRONT_FUNCTION_NAME`, `CREATED_ID`, `CREATED_BY`, `CREATION_DATE`, `CREATED_BY_IP`, `CREATED_FULL_NAME`, `LAST_UPDATED_ID`, `LAST_UPDATED_BY`, `LAST_UPDATE_DATE`, `LAST_UPDATED_BY_IP`, `LAST_UPDATED_FULL_NAME`, `TENANT_ID`, `VERSION`) VALUES (459508800388864, 'JC_INQ_QUOTATION_WAIT_FORM_PRODUCT_1000', 'INQ_READ', 'JC_INQ_QUOTATION', '集采询价单待报价', 'WAIT_FORM', 'PRODUCT', 1000, 'N', 'DATA_PERMISSION_ALL_VENDOR', 'ALL', 'SQL', 'SELECT * FROM (SELECT\n        sou_project.PROJECT_ID AS businessId,\n        sou_project.sou_no AS businessCode,\n        \'集采报价\' AS moduleName,\n        \'/jcManagement/jcQuotation\' AS searchUrl,\n        CONCAT(\'集采\',\'-\',sou_project.sou_no,\'-\',DATE_FORMAT(sou_project.ORDER_START_TIME, \'%Y.%m.%d\'),\'至\',DATE_FORMAT(sou_project.ORDER_END_TIME,\'%Y.%m.%d\'),\',请及时报价\') AS title,\n		  sou_project.CREATION_DATE AS creationDate,\n		  sou_project.CREATED_FULL_NAME AS creationName	  \n            FROM\n            scc_sou_project sou_project \n            LEFT JOIN scc_sou_vendor v ON v.PROJECT_ID = sou_project.PROJECT_ID\n            WHERE\n            sou_project.SOU_TYPE = \'ext_pur_inq\' \n				AND sou_project.ORDER_END_TIME > NOW() \n				AND NOT  EXISTS( \n				SELECT 1 FROM scc_sou_order o \n					WHERE o.PROJECT_ID = sou_project.PROJECT_ID AND o.`ROUND` = sou_project.CURRENT_ROUND\n					AND o.ORDER_STATUS = \'SUBMISSION\'\n				)\n				AND v.VENDOR_ID = ${user.companyId}\n				) t', NULL, NULL, NULL, 'jcQuotation', NULL, NULL, 8123195817787648, 'super', '2024-01-06 18:13:17', '10.254.103.203', '超级管理员', 8123195817787648, 'super', '2024-01-06 18:19:32', '10.254.103.203', '超级管理员', NULL, 0);
DELETE FROM `scc_base_todolist_config` WHERE `TODOLIST_CONFIG_ID`=459374128746240;
INSERT INTO `scc_base_todolist_config` (`TODOLIST_CONFIG_ID`, `UNIQUE_CODE`, `CONFIG_MODULE`, `CONFIG_CODE`, `CONFIG_NAME`, `CONFIG_TYPE`, `CONFIG_FROM`, `CONFIG_VERSION`, `CONFIG_STATUS`, `ROLE_CODE`, `DIMENSION`, `CONFIG_MODE`, `SQL_LANGUAGE`, `URL_ADDRESS`, `URL_PARAMS`, `URL_MAPPING`, `FRONT_ROUTE_NAME`, `FRONT_FORM_NAME`, `FRONT_FUNCTION_NAME`, `CREATED_ID`, `CREATED_BY`, `CREATION_DATE`, `CREATED_BY_IP`, `CREATED_FULL_NAME`, `LAST_UPDATED_ID`, `LAST_UPDATED_BY`, `LAST_UPDATE_DATE`, `LAST_UPDATED_BY_IP`, `LAST_UPDATED_FULL_NAME`, `TENANT_ID`, `VERSION`) VALUES (459374128746240, 'INQUIRY_ORDER_NEED_QUOTATION_NOTICE_WAIT_FORM_PRODUCT_1000', 'INQ_READ', 'INQUIRY_ORDER_NEED_QUOTATION_NOTICE', '临采询价单需要报价信息', 'WAIT_FORM', 'PRODUCT', 1000, 'N', 'DATA_PERMISSION_ALL_VENDOR', 'ALL', 'SQL', 'SELECT * FROM (SELECT\n        sou_project.PROJECT_ID AS businessId,\n        sou_project.sou_no AS businessCode,\n        \'临采报价\' AS moduleName,\n        \'/inquiryVendor/orders\' AS searchUrl,\n        CONCAT(\'临采\',\'-\',sou_project.sou_no,\'-\',DATE_FORMAT(sou_project.ORDER_START_TIME, \'%Y.%m.%d\'),\'至\',DATE_FORMAT(sou_project.ORDER_END_TIME,\'%Y.%m.%d\'),\',请及时报价\') AS title,\n		  sou_project.CREATION_DATE AS creationDate,\n		  sou_project.CREATED_FULL_NAME AS creationName,\n		  v.VENDOR_ID,v.VENDOR_NAME	  \n            FROM scc_sou_project sou_project \n            LEFT JOIN scc_sou_vendor v ON v.PROJECT_ID = sou_project.PROJECT_ID\n            WHERE\n            sou_project.SOU_TYPE = \'inq\' \n				AND sou_project.ORDER_END_TIME > NOW() \n				AND NOT  EXISTS( \n				SELECT 1 FROM scc_sou_order o \n					WHERE o.PROJECT_ID = sou_project.PROJECT_ID AND o.`ROUND` = sou_project.CURRENT_ROUND\n					AND o.ORDER_STATUS = \'SUBMISSION\'\n				)\n				AND v.VENDOR_ID = ${user.companyId}\n				) t', NULL, NULL, NULL, 'inquiryOrders', NULL, 'inquiryOrders', 8123195817787648, 'super', '2024-01-05 23:57:19', '10.254.103.203', '超级管理员', 8123195817787648, 'super', '2024-01-06 17:55:04', '10.254.103.203', '超级管理员', NULL, 0);
